ba8fdfd6fbf3447aa1657a7a2ac1ca91/results-780675/cuda-nbody/logs/e1/e03a3d880aa74e0e/search/attempt-001/sample-2.log"], "mean_seconds": 0.0019851423390623082, "reason": "", "score": 0.4824287258795003, "status": "valid", "times": [0.0019855478608380044, 0.001985037957185298, 0.0019848411991636224], "tree_hash": "0135990c89b21b09f44a27b5905a909124cc1a5e"}, "search_stop_reason": "budget_exhausted", "selections": [{"decision": {"action": "read", "base_id": "", "idea_ids": [], "rationale": "Inspect the fastest correct measured candidate's actual kernel before deciding what to integrate. T1 is valid/correct at 0.00113314 s versus the valid baseline at 0.00185035 s; T2 is slower, T3 is incorrect, and T4 is approximately baseline. I will not infer compatibility or combine ideas without inspecting source.", "read": {"ids": ["a8795a3f5dd140e9"], "offset": 0, "operation": "source", "path": "src/nbody_kernel.cu", "query": ""}, "source_ids": []}, "id": "memory-select-e1-r1-t1", "read_result": {"commit": "6f2654ac59cb6fcc13b6d506feefd5e6ae26a559", "file_sha256": "d08bba6e9cd72095cdc4ec90a028d409bc26c78e4f49d1c7c13a5cb8c1e59c6a", "id": "a8795a3f5dd140e9", "next_offset": null, "offset_unit": "characters", "path": "src/nbody_kernel.cu", "schema": "hpc-forest-memory-v1", "snapshot_digest": "3fd853791ed468aa0f0ddf72e7446356e1c618f2c8a021282cdaa7046a450ad3", "text": "struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

enum { kSourceTileSize = 256 };

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    const bool active = i < n;

    __shared__ float tile_x[kSourceTileSize];
    __shared__ float tile_y[kSourceTileSize];
    __shared__ float tile_z[kSourceTileSize];
    __shared__ float tile_mass[kSourceTileSize];

    const float G = 1.0f;
    const float softening = 0.001f;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    for (int tile_start = 0; tile_start < n;) {
        int tile_count = n - tile_start;
        if (tile_count > kSourceTileSize) {
            tile_count = kSourceTileSize;
        }

        for (int k = threadIdx.x; k < tile_count; k += blockDim.x) {
            const int source_index = tile_start + k;
            tile_x[k] = in[source_index].x;
            tile_y[k] = in[source_index].y;
            tile_z[k] = in[source_index].z;
            tile_mass[k] = in[source_index].mass;
        }
        __syncthreads();

        if (active) {
            for (int k = 0; k < tile_count; ++k) {
                const int j = tile_start + k;
                if (i == j) {
                    continue;
                }

                const float dx = tile_x[k] - in[i].x;
                const float dy = tile_y[k] - in[i].y;
                const float dz = tile_z[k] - in[i].z;

                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * in[i].mass * tile_mass[k]) / (distSq * dist);

                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }

        __syncthreads();
        tile_start += tile_count;
    }

    if (active) {
        Particle p = in[i];
        p.vx += (fx / p.mass) * dt;
        p.vy += (fy / p.mass) * dt;
        p.vz += (fz / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

        out[i] = p;
    }
}
